1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseMarkdownFile } from './frontmatter';
4	import { renderMarkdown } from './markdown';
5	import { Page, renderIndexHtml, renderPageHtml } from './page';
6	
7	export interface BuildOptions {
8	  contentDir: string;
9	  outputDir: string;
10	}
11	
12	export interface BuildResult {
13	  pages: Page[];
14	  outputDir: string;
15	}
16	
17	function findMarkdownFiles(dir: string): string[] {
18	  if (!fs.existsSync(dir)) {
19	    throw new Error(`Content directory not found: ${dir}`);
20	  }
21	
22	  const results: string[] = [];
23	  const entries = fs.readdirSync(dir, { withFileTypes: true });
24	
25	  for (const entry of entries) {
26	    const fullPath = path.join(dir, entry.name);
27	    if (entry.isDirectory()) {
28	      results.push(...findMarkdownFiles(fullPath));
29	    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
30	      results.push(fullPath);
31	    }
32	  }
33	
34	  return results.sort();
35	}
36	
37	function slugFromPath(contentDir: string, filePath: string): string {
38	  const relative = path.relative(contentDir, filePath);
39	  const withoutExt = relative.replace(/\.md$/i, '');
40	  return withoutExt.split(path.sep).join('/');
41	}
42	
43	function titleFromSlug(slug: string): string {
44	  const base = slug.split('/').pop() || slug;
45	  return base
46	    .replace(/[-_]+/g, ' ')
47	    .replace(/\b\w/g, (char) => char.toUpperCase());
48	}
49	
50	export function buildPage(contentDir: string, filePath: string): Page {
51	  const raw = fs.readFileSync(filePath, 'utf-8');
52	  const { data, content } = parseMarkdownFile(raw);
53	  const slug = slugFromPath(contentDir, filePath);
54	  const html = renderMarkdown(content);
55	
56	  const title = typeof data.title === 'string' && data.title.trim() ? data.title : titleFromSlug(slug);
57	  const date = typeof data.date === 'string' && data.date.trim() ? data.date : null;
58	  const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
59	
60	  return {
61	    slug,
62	    title,
63	    date,
64	    tags,
65	    html,
66	    sourcePath: filePath,
67	    outputPath: `${slug}.html`,
68	  };
69	}
70	
71	export function buildSite(options: BuildOptions): BuildResult {
72	  const contentDir = path.resolve(options.contentDir);
73	  const outputDir = path.resolve(options.outputDir);
74	
75	  const files = findMarkdownFiles(contentDir);
76	  const pages = files.map((file) => buildPage(contentDir, file));
77	
78	  fs.mkdirSync(outputDir, { recursive: true });
79	
80	  for (const page of pages) {
81	    const destPath = path.join(outputDir, page.outputPath);
82	    fs.mkdirSync(path.dirname(destPath), { recursive: true });
83	    fs.writeFileSync(destPath, renderPageHtml(page), 'utf-8');
84	  }
85	
86	  const indexPath = path.join(outputDir, 'index.html');
87	  fs.writeFileSync(indexPath, renderIndexHtml(pages), 'utf-8');
88	
89	  return { pages, outputDir };
90	}
