11	function escapeHtml(value: string): string {
12	  return value
13	    .replace(/&/g, '&amp;')
14	    .replace(/</g, '&lt;')
15	    .replace(/>/g, '&gt;')
16	    .replace(/"/g, '&quot;')
17	    .replace(/'/g, '&#39;');
18	}
19	
20	export function renderPageHtml(page: Page): string {
21	  const tagsHtml = page.tags.length
22	    ? `<ul class="tags">${page.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
23	    : '';
24	  const dateHtml = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';
25	
26	  return `<!DOCTYPE html>
27	<html lang="en">
28	<head>
29	<meta charset="UTF-8">
30	<title>${escapeHtml(page.title)}</title>
31	</head>
32	<body>
33	<a href="index.html">&larr; Back to index</a>
34	<h1>${escapeHtml(page.title)}</h1>
35	${dateHtml}
36	${tagsHtml}
37	<article>
38	${page.html}
39	</article>
40	</body>
41	</html>
42	`;
43	}
44	
45	export function renderIndexHtml(pages: Page[]): string {
46	  const items = pages
47	    .map((page) => {
48	      const dateHtml = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
49	      return `<li><a href="${escapeHtml(page.outputPath)}">${escapeHtml(page.title)}</a>${dateHtml}</li>`;
50	    })
51	    .join('\n');
52	
53	  return `<!DOCTYPE html>
54	<html lang="en">
55	<head>
56	<meta charset="UTF-8">
57	<title>Index</title>
58	</head>
59	<body>
60	<h1>Index</h1>
61	<ul class="pages">
62	${items}
63	</ul>
64	</body>
65	</html>
66	`;
67	}
