1	import matter from 'gray-matter';
2	
3	export interface FrontmatterData {
4	  title?: string;
5	  date?: string;
6	  tags?: string[];
7	  [key: string]: unknown;
8	}
9	
10	export interface ParsedMarkdown {
11	  data: FrontmatterData;
12	  content: string;
13	}
14	
15	const FRONTMATTER_BLOCK = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;
16	
17	/**
18	 * Parses a single `key: value` line from a YAML-ish frontmatter block.
19	 * Supports quoted strings, bracketed arrays (`[a, b, c]`) and bare scalars.
20	 */
21	function parseValue(raw: string): unknown {
22	  const value = raw.trim();
23	
24	  if (
25	    (value.startsWith('"') && value.endsWith('"')) ||
26	    (value.startsWith("'") && value.endsWith("'"))
27	  ) {
28	    return value.slice(1, -1);
29	  }
30	
31	  if (value.startsWith('[') && value.endsWith(']')) {
32	    const inner = value.slice(1, -1).trim();
33	    if (inner === '') return [];
34	    return inner.split(',').map((item) => stripQuotes(item.trim()));
35	  }
36	
37	  return value;
38	}
39	
40	function stripQuotes(value: string): string {
41	  if (
42	    (value.startsWith('"') && value.endsWith('"')) ||
43	    (value.startsWith("'") && value.endsWith("'"))
44	  ) {
45	    return value.slice(1, -1);
46	  }
47	  return value;
48	}
49	
50	/**
51	 * gray-matter only parses JSON frontmatter out of the box, so YAML blocks
52	 * (the format used throughout this project) must be split out manually
53	 * with a simple `key: value` line parser and merged into gray-matter's
54	 * output afterwards.
55	 */
56	export function parseYamlFrontmatter(block: string): FrontmatterData {
57	  const data: FrontmatterData = {};
58	  const lines = block.split(/\r?\n/);
59	
60	  for (const line of lines) {
61	    if (!line.trim() || line.trim().startsWith('#')) continue;
62	
63	    const separatorIndex = line.indexOf(':');
64	    if (separatorIndex === -1) continue;
65	
66	    const key = line.slice(0, separatorIndex).trim();
67	    const rawValue = line.slice(separatorIndex + 1).trim();
68	    if (!key) continue;
69	
70	    if (key === 'tags') {
71	      if (rawValue.startsWith('[')) {
72	        data.tags = parseValue(rawValue) as string[];
73	      } else if (rawValue === '') {
74	        data.tags = [];
75	      } else {
76	        data.tags = rawValue.split(',').map((tag) => stripQuotes(tag.trim())).filter(Boolean);
77	      }
78	    } else {
79	      data[key] = parseValue(rawValue);
80	    }
81	  }
82	
83	  return data;
84	}
85	
86	export function parseMarkdownFile(raw: string): ParsedMarkdown {
87	  let content = raw;
88	  let grayMatterData: Record<string, unknown> = {};
89	
90	  try {
91	    const parsed = matter(raw);
92	    content = parsed.content;
93	    grayMatterData = parsed.data || {};
94	  } catch {
95	    // gray-matter cannot parse YAML frontmatter out of the box; fall back
96	    // to manually stripping the block below.
97	  }
98	
99	  const match = FRONTMATTER_BLOCK.exec(raw);
100	  let yamlData: FrontmatterData = {};
101	  if (match) {
102	    yamlData = parseYamlFrontmatter(match[1]);
103	    content = raw.slice(match[0].length);
104	  }
105	
106	  const data: FrontmatterData = { ...grayMatterData, ...yamlData };
107	
108	  return { data, content: content.trim() };
109	}
